    @Test void sameHumanDifferentAccountsCannotBeMakerAndChecker() throws Exception {referred();var other=account(UserRole.APPROVER);var u=users.findById(other.user().getId()).orElseThrow();u.setOperatorPersonId(maker.user().getOperatorPersonId());users.saveAndFlush(u);assertThrows(ResponseStatusException.class,()->reporting.propose(maker.user().getId(),maker.sid(),referral.payload().id(),u.getId(),UUID.randomUUID(),facts()));}
    @Test void actualAssignedListsAndMetadataNeverIncludeRationaleOrConclusion() throws Exception {var r=prepared();for(var a:List.of(maker,checker)){String encoded=json.writeValueAsString(reporting.list(a.user().getId(),a.sid(),0));assertTrue(encoded.contains(r.payload().id().toString()));assertFalse(encoded.contains(facts().rationale()));assertFalse(encoded.contains("REPORT_REQUIRED"));}String payload=jdbc.queryForObject("SELECT payload FROM compliance_reviews WHERE id=?",String.class,r.payload().id());assertFalse(payload.contains(facts().rationale()));assertFalse(new String(jdbc.queryForObject("SELECT facts_cipher FROM compliance_reviews WHERE id=?",byte[].class,r.payload().id()),StandardCharsets.UTF_8).contains(facts().rationale()));}
