    @Test void sameKeyReplaysExactTargetAndFactsButChangedReasonConflicts() throws Exception {referred();UUID key=UUID.randomUUID();var r=request(key,facts());assertEquals(r.payload().id(),request(key,facts()).payload().id());assertThrows(ResponseStatusException.class,()->request(key,new ReportingReviewService.Facts(facts().conclusion(),"다른 사유")));assertEquals(1,count("compliance_reviews"));}
    @Test void simultaneousSameKeyCreatesOneReview() throws Exception {referred();UUID key=UUID.randomUUID();try(var pool=Executors.newFixedThreadPool(2)){var gate=new CountDownLatch(1);var fs=new ArrayList<Future<UUID>>();for(int i=0;i<2;i++)fs.add(pool.submit(()->{gate.await();return request(key,facts()).payload().id();}));gate.countDown();assertEquals(fs.get(0).get(12,TimeUnit.SECONDS),fs.get(1).get(12,TimeUnit.SECONDS));}assertEquals(1,count("compliance_reviews"));}
