    @Test void decisionAuditFailureRollsBackProofAndDecisionThenRetrySucceeds() throws Exception {var r=prepared();var p=reportProof(checker,r,true);doThrow(new IllegalStateException("격리 감사 실패")).when(audit).record(any(),eq("COMPLIANCE_REVIEW_DECIDED"),anyString(),anyString(),anyString());assertThrows(IllegalStateException.class,()->reportDecide(r,true,p));assertEquals(0,count("compliance_review_decisions"));assertFalse(jdbc.queryForObject("SELECT consumed FROM operator_authorization_challenges WHERE id=?",Boolean.class,p.challengeId()));reset(audit);assertEquals("APPROVED",reportDecide(r,true,p).status());}
    @Test void oppositeDecisionCannotUseApprovalSignature() throws Exception {var r=prepared();var p=reportProof(checker,r,true);assertThrows(ResponseStatusException.class,()->reportDecide(r,false,p));assertEquals(0,count("compliance_review_decisions"));assertFalse(jdbc.queryForObject("SELECT consumed FROM operator_authorization_challenges WHERE id=?",Boolean.class,p.challengeId()));}
    @Test void actualApproveRejectRaceCommitsExactlyOneDecision() throws Exception {var r=prepared();var yes=reportProof(checker,r,true);var no=reportProof(checker,r,false);try(var pool=Executors.newFixedThreadPool(2)){var gate=new CountDownLatch(1);var fs=new ArrayList<Future<Boolean>>();for(boolean approve:new boolean[]{true,false})fs.add(pool.submit(()->{gate.await();try{reportDecide(r,approve,approve?yes:no);return true;}catch(ResponseStatusException e){return false;}}));gate.countDown();int successes=0;for(var f:fs)if(f.get(12,TimeUnit.SECONDS))successes++;assertEquals(1,successes);}assertEquals(1,count("compliance_review_decisions"));blocked();}
    @Test void auditAndGeneralDossierDoNotCopyDecisionOrReason() throws Exception {var r=prepared();reportDecide(r,true,reportProof(checker,r,true));String all=jdbc.queryForList("SELECT action,detail FROM security_audit WHERE target=?", "compliance-review:"+r.payload().id()).toString();assertFalse(all.contains(facts().rationale()));assertFalse(all.contains("REPORT_REQUIRED"));String bundle=jdbc.queryForObject("SELECT items FROM edd_case_dossiers WHERE id=?",String.class,r.payload().dossier().id());assertFalse(bundle.contains(r.payload().id().toString()));assertFalse(bundle.contains("REPORT_REQUIRED"));}
    @Test void newTablesRejectAllMutationStatements() throws Exception {var r=prepared();reportDecide(r,true,reportProof(checker,r,true));for(String table:List.of("compliance_reviews","compliance_review_views","compliance_review_decisions")){for(String sql:List.of("UPDATE "+table+" SET "+(table.equals("compliance_reviews")?"payload=payload":table.equals("compliance_review_views")?"page=page":"approved=approved"),"DELETE FROM "+table,"TRUNCATE "+table+" CASCADE"))assertThrows(DataAccessException.class,()->jdbc.execute(sql));}assertEquals(1,count("compliance_review_decisions"));}
    @Test void oldEightKindSchemaFailsWithoutTransformingExistingHistory() throws Exception {var r=prepared();String sql=new org.springframework.core.io.ClassPathResource("security/schema.sql").getContentAsString(StandardCharsets.UTF_8);assertThrows(DataAccessException.class,()->new TransactionTemplate(manager).executeWithoutResult(t->{jdbc.execute("ALTER TABLE operator_approval_bindings DROP CONSTRAINT operator_approval_bindings_kind_check");jdbc.execute("ALTER TABLE operator_approval_bindings ADD CONSTRAINT operator_approval_bindings_kind_check CHECK(kind IN ('ROLE','MFA_RECOVERY','ACCESS_REVIEW','TRADING_RESTRICTION','EDD_REVIEW','EDD_ADDRESS_REVIEW','EDD_FUNDS_REVIEW','EDD_WEALTH_REVIEW')) NOT VALID");jdbc.execute(sql);}));assertEquals(1,count("compliance_reviews"));assertTrue(jdbc.queryForObject("SELECT pg_get_constraintdef(oid) FROM pg_constraint WHERE conname='operator_approval_bindings_kind_check'",String.class).contains("STR_REVIEW"));}
