    @Test void realHttpProposalInspectionOptionsAndBoundSignatureUseStoredFacts() throws Exception {
        referred();String body=json.writeValueAsString(new ReportingReviewController.Proposal(referral.payload().id(),checker.user().getId(),facts()));String raw=mvc.perform(post("/api/admin/compliance/reviews").header("Authorization","Bearer "+maker.access()).header("Idempotency-Key",UUID.randomUUID()).contentType(MediaType.APPLICATION_JSON).content(body)).andExpect(status().isOk()).andExpect(header().string("Cache-Control","no-store")).andReturn().getResponse().getContentAsString();var r=json.readValue(raw,ReportingReviewService.Review.class);
        mvc.perform(post("/api/admin/compliance/reviews/"+r.payload().id()+"/inspect").header("Authorization","Bearer "+checker.access())).andExpect(status().isOk()).andExpect(jsonPath("$.facts.rationale").value(facts().rationale()));
        var o=json.readValue(mvc.perform(post("/api/admin/compliance/reviews/"+r.payload().id()+"/approve/options").header("Authorization","Bearer "+checker.access()).contentType(MediaType.APPLICATION_JSON).content(json.writeValueAsString(new ReportingReviewController.Confirmation(r.payloadHash())))).andExpect(status().isOk()).andReturn().getResponse().getContentAsString(),ReportingReviewService.Confirmation.class).authentication();
        var p=new OperatorMfaService.AuthorizationProof(o.challengeId(),checker.key().assertion(o,"http://localhost:3003",true,counter.incrementAndGet(),null));mvc.perform(post("/api/admin/compliance/reviews/"+r.payload().id()+"/approve").header("Authorization","Bearer "+checker.access()).contentType(MediaType.APPLICATION_JSON).content(json.writeValueAsString(new ReportingReviewController.Decision(r.payloadHash(),p)))).andExpect(status().isOk()).andExpect(jsonPath("$.status").value("APPROVED"));blocked();
    }
    @Test void everyFrozenPageIsRequiredIncludingFinalPartialPage() throws Exception {
        reviewed();var c=service.status(customer.getId());
        // 페이지 경계를 검증하는 과거 자료 요청 표본만 추가한다. 내용 확인 완료나 외부 진위를 합성하지 않는다.
        for(int i=0;i<28;i++)jdbc.update("INSERT INTO edd_evidence_requests(id,case_id,user_id,assessment_id,purpose,requester_id,requester_person,request_key,expires_at,created_at) VALUES(?,?,?,?,'SOURCE_OF_FUNDS',?,?,?,clock_timestamp()-interval '2 days',clock_timestamp()-interval '3 days')",UUID.randomUUID(),c.id(),customer.getId(),c.latestAssessment(),maker.user().getId(),maker.user().getOperatorPersonId(),UUID.randomUUID());
        referral=propose(EddService.Finding.COMPLIANCE_ESCALATION);decide(referral,true,proof(checker,referral,true));var r=request(UUID.randomUUID(),facts());assertEquals(2,r.payload().dossier().pageCount());
        assertEquals(25,reporting.inspect(checker.user().getId(),checker.sid(),r.payload().id(),0).dossier().items().size());assertThrows(ResponseStatusException.class,()->reporting.options(checker.user().getId(),checker.sid(),r.payload().id(),r.payloadHash(),true));
        assertEquals(3,reporting.inspect(checker.user().getId(),checker.sid(),r.payload().id(),1).dossier().items().size());assertNotNull(reporting.options(checker.user().getId(),checker.sid(),r.payload().id(),r.payloadHash(),true));
    }
    ReportingReviewService.Review datedCopy(ReportingReviewService.Review original,boolean damaged) {
        // 만료·다른 문맥의 암호문을 별도 과거 표본으로 추가한다. 실제 요청이나 불변 결정을 갱신하지 않는다.
        var raw=(tools.jackson.databind.node.ObjectNode)json.valueToTree(original.payload());UUID id=UUID.randomUUID();raw.put("id",id.toString()).put("expiresAt",Instant.now().minusSeconds(1).toString());
        var p=json.readValue(json.writeValueAsString(raw),ReportingReviewService.Payload.class);String hash=verifier.digest(raw);
        byte[] cipher=damaged?jdbc.queryForObject("SELECT facts_cipher FROM compliance_reviews WHERE id=?",byte[].class,original.payload().id()):reportingCrypto.encrypt("COMPLIANCE_REVIEW:"+id+":"+p.userId()+":"+p.caseId()+":"+p.referralId()+":"+p.factsMac(),json.writeValueAsBytes(facts()));
        jdbc.update("INSERT INTO compliance_reviews(id,case_id,user_id,referral_id,requester_id,checker_id,request_key,payload,payload_hash,facts_cipher,expires_at) VALUES(?,?,?,?,?,?,?,?,?,?,?)",id,p.caseId(),p.userId(),p.referralId(),p.requesterId(),p.checkerId(),UUID.randomUUID(),json.writeValueAsString(raw),hash,cipher,java.sql.Timestamp.from(p.expiresAt()));return new ReportingReviewService.Review(p,hash,"EXPIRED");
    }
    @Test void expiredRequestIsReadableButCannotIssueNewDecision() throws Exception {
        var r=datedCopy(prepared(),false);assertEquals(facts(),reporting.inspect(checker.user().getId(),checker.sid(),r.payload().id(),0).facts());assertEquals(409,assertThrows(ResponseStatusException.class,()->reporting.options(checker.user().getId(),checker.sid(),r.payload().id(),r.payloadHash(),true)).getStatusCode().value());
    }
    @Test void copiedCipherFromAnotherReviewFailsWithoutPlaintextOrReceipt() throws Exception {
        var r=datedCopy(prepared(),true);var error=assertThrows(IllegalStateException.class,()->reporting.inspect(checker.user().getId(),checker.sid(),r.payload().id(),0));assertNull(error.getCause());assertFalse(error.toString().contains(facts().rationale()));assertEquals(0,jdbc.queryForObject("SELECT count(*) FROM compliance_review_views WHERE review_id=?",Long.class,r.payload().id()));
    }
    @Test void signatureForDifferentBusinessKindCannotApproveReportingReview() throws Exception {
        var r=prepared();inspectAll(checker,r);UUID other=UUID.randomUUID();
        // 다른 업무의 유효한 인증 결합만 만든다. 허구의 금융 확정·외부 보고 성공을 생성하지 않는다.
        new TransactionTemplate(manager).executeWithoutResult(t->mfa.bindApproval(OperatorMfaService.ApprovalKind.EDD_REVIEW,other,maker.user().getId(),r.payload().requesterVersion(),r.payloadHash(),r.payload().expiresAt()));
        var o=new TransactionTemplate(manager).execute(t->mfa.approvalOptions(checker.user().getId(),checker.sid(),OperatorMfaService.ApprovalKind.EDD_REVIEW,other,r.payloadHash(),true));
        var proof=new OperatorMfaService.AuthorizationProof(o.challengeId(),checker.key().assertion(o,"http://localhost:3003",true,counter.incrementAndGet(),null));assertThrows(ResponseStatusException.class,()->reportDecide(r,true,proof));assertFalse(jdbc.queryForObject("SELECT consumed FROM operator_authorization_challenges WHERE id=?",Boolean.class,proof.challengeId()));assertEquals(0,count("compliance_review_decisions"));
    }

